const trn=v=>String(v).replace('.',',');
function pz(){const a=A();return a.pz&&typeof a.pz==='object'?a.pz:(a.pz={})}
function scoreBox(){const a=A();const ex=multi('sinav').filter(x=>SCX[x]);const P=pz();if(!ex.length)return '';
  return '<div class="yr-sc">'+ex.map(x=>{const c=SCX[x];let h=`<label class="yr-other yr-scl">${c.lab}`;
    if(c.sel)h+=`<select data-pz="${x}"><option value="">Seç</option>${c.sel.map(v=>`<option value="${v}"${String(P[x])===String(v)?' selected':''}>${trn(v)}</option>`).join('')}</select>`;
    else h+=`<input data-pz="${x}" type="number" inputmode="numeric" min="${c.min}" max="${c.max}" value="${esc(P[x]||'')}" placeholder="${c.min} ile ${c.max} arası">`;
    h+='</label>';
    if(c.old)h+=`<label class="yr-other yr-scl yr-old">${c.old.lab}<input data-pz="${x}_eski" type="number" inputmode="numeric" min="${c.old.min}" max="${c.old.max}" value="${esc(P[x+'_eski']||'')}" placeholder="0 ile 120 arası"></label>`;
    if(c.note)h+=`<p class="yr-scn">${c.note}</p>`;return h}).join('')+'<p class="yr-err yr-sce" hidden></p></div>'}
function puanText(){const P=pz();return multi('sinav').filter(x=>SCX[x]).map(x=>{let t='';if(P[x])t=x+' '+trn(P[x]);if(P[x+'_eski'])t+=(t?' (eski ölçek '+P[x+'_eski']+')':x+' eski ölçek '+P[x+'_eski']);return t}).filter(Boolean).join(' · ')}
const CEFR=['A1','A2','B1','B2','C1','C2'];
function scoreLevel(){const P=pz();const L=[];const n=k=>P[k]!==undefined&&P[k]!==''?+P[k]:NaN;
  let v=n('IELTS');if(!isNaN(v))L.push(['IELTS',v>=8.5?'C2':v>=7?'C1':v>=5.5?'B2':v>=4?'B1':'A2']);
  v=n('TOEFL');if(!isNaN(v))L.push(['TOEFL',v>=6?'C2':v>=5?'C1':v>=4?'B2':v>=3?'B1':v>=2?'A2':'A1']);
  else{v=n('TOEFL_eski');if(!isNaN(v))L.push(['TOEFL',v>=114?'C2':v>=95?'C1':v>=72?'B2':v>=44?'B1':v>=24?'A2':'A1'])}
  v=n('Duolingo');if(!isNaN(v))L.push(['Duolingo',v>=155?'C2':v>=130?'C1':v>=100?'B2':v>=60?'B1':'A2']);
  v=n('Cambridge');if(!isNaN(v))L.push(['Cambridge',v>=200?'C2':v>=180?'C1':v>=160?'B2':v>=140?'B1':v>=120?'A2':'A1']);
  if(!L.length)return null;L.sort((x,y)=>CEFR.indexOf(y[1])-CEFR.indexOf(x[1]));return {lvl:L[0][1],src:L[0][0]}}
function effEng(){const s=scoreLevel();return s?s.lvl:A().eng}
