function bindPz(){const P=pz();root.querySelectorAll('[data-pz]').forEach(i=>{const h=()=>{P[i.dataset.pz]=i.value;A().puan=puanText();save()};i.addEventListener('input',h);i.addEventListener('change',h)})}
function pzErr(){const P=pz();for(const x of multi('sinav')){const c=SCX[x];if(!c)continue;const chk=(k,mn,mx)=>{const v=P[k];if(v===undefined||v==='')return '';const f=+v;return (isNaN(f)||f<mn||f>mx)?`${x} puanı ${mn} ile ${mx} arasında olmalı.`:''};
  let e=c.sel?'':chk(x,c.min,c.max);if(!e&&c.old)e=chk(x+'_eski',c.old.min,c.old.max);if(e)return e}return ''}
function shake(x){x.classList.add('yr-shake');setTimeout(()=>x.classList.remove('yr-shake'),500)}
function toast(t){let e=document.querySelector('.yr-toast');if(!e){e=document.createElement('div');e.className='yr-toast';document.body.appendChild(e)}e.textContent=t;e.classList.add('on');clearTimeout(e._t);e._t=setTimeout(()=>e.classList.remove('on'),2200)}
// ---------- hesaplama
function profile(){const p={},mx={};TY.forEach(t=>{p[t]=0;mx[t]=0});
  SEC.forEach(s=>s.i.forEach((x,i)=>{mx[x[0]]++;if(multi(s.k).includes(String(i)))p[x[0]]++}));
  const pc={};TY.forEach(t=>pc[t]=mx[t]?Math.round(p[t]/mx[t]*100):0);return pc}
const norm=s=>(s||'').toLocaleLowerCase('tr').replace(/[^a-zçğıöşü0-9 ]/g,' ').trim();
const LMAP={'Almanca':['Almanya','Avusturya','İsviçre'],'Fransızca':['Fransa','Belçika','İsviçre'],'İtalyanca':['İtalya','İsviçre'],'İspanyolca':['İspanya'],'Japonca':['Japonya']};
const UL=Object.fromEntries(D.ulkeler.map(u=>[u.ad,u]));
const EUR=['Birleşik Krallık','İrlanda','Hollanda','Belçika','Fransa','İspanya','Almanya','Avusturya','İsviçre','İtalya','Malta','Macaristan','Polonya','Çekya','Estonya','Letonya','Litvanya','İsveç','Finlandiya','Danimarka'];
const REGQ=[['Kuzey Amerika',['ABD','Kanada']],['Avrupa',EUR],['Asya Pasifik',['Japonya','Avustralya','Yeni Zelanda']],['Orta Doğu',['Dubai']]];
const EN=new Set(['ABD','Birleşik Krallık','Kanada','İrlanda','Avustralya','Yeni Zelanda','Malta']);
function cscore(u,prog){const a=A();let s=0;const why=[];const want=multi('ulke');const bud=+(a.butce||0);
  if(want.includes(u.ad)){s+=4;why.push('Aklındaki ülkelerden biri')}
  if(a.uzak==='yakin'){if(u.uzak==='yakin'){s+=2;why.push('Eve uçakla birkaç saat')}else s-=4}
  if(a.uzak==='uzak'&&u.uzak==='uzak'){s+=2;why.push('Okyanus ötesi deneyim istedin')}
  const ct=prog==='Prep'?u.lise_maliyet:u.maliyet;
  if(bud){if(ct>bud)s-=6;else{s+=1;why.push('Belirttiğin bütçe aralığına uyan bir seçenek')}}
  if(a.burs==='1'&&ct<=1)s+=1;
  for(const l of multi('dil'))if((LMAP[l]||[]).includes(u.ad)){s+=2;why.push(l+' bilmen burada artı')}
  if(a.sehir==='kampus'&&u.kampus){s+=1;why.push('Kampüs hayatı güçlü')}
  const P=pz();if(u.ad==='ABD'&&(prog==='Campus')&&(P.SAT||P.ACT)){s+=2;why.push((P.SAT?'SAT':'ACT')+' puanın ABD başvurusunda işine yarar')}
  const el=scoreLevel();if(el&&CEFR.indexOf(el.lvl)>=4&&(prog==='Campus'||prog==='Next')){s+=1;why.push('Sınav puanın İngilizce eğitime hazır olduğunu gösteriyor')}
  return {s,why:[...new Set(why)]}}
function compute(){
  const a=A();const pc=profile();const ord=[...TY].sort((x,y)=>pc[y]-pc[x]);const code=ord.slice(0,2);
  const progs=multi('prog');const q=norm(a.bolum);const qw=q.split(' ').filter(w=>w.length>3);
  const lv=progs.includes('Campus')||progs.includes('Prep')?'L':'Y';
  const KB=Object.fromEntries(D.bolumler.map(b=>[b.ad,b]));
  const BL=D.bolumler.filter(b=>lv==='L'?b.sv!=='Y':b.sv!=='L').map(b=>{let sc=(pc[b.kod[0]]||0)+(pc[b.kod[1]]||0)*.6;const nb=norm(b.ad);let txt=false;
    if(q.length>2&&(nb.includes(q)||qw.some(w=>nb.includes(w)))){sc+=80;txt=true}return {...b,sc,txt}}).sort((x,y)=>y.sc-x.sc);
  const pick=[],gc={};for(const b of BL){if((gc[b.grup]||0)>=3)continue;pick.push(b);gc[b.grup]=(gc[b.grup]||0)+1;if(pick.length>=8)break}
  const rank={};BL.forEach((b,i)=>rank[b.ad]=i);
  const topSet=new Set(BL.slice(0,20).map(b=>b.ad));pick.forEach(b=>topSet.add(b.ad));
  const bolWhy=b=>{const r=[];const t=[...new Set(b.kod.split(''))].filter(x=>ord.slice(0,3).includes(x)&&pc[x]>0);
    if(b.txt)r.push('Aklındaki bölümle örtüşüyor');
    if(t.length)r.push(`${t.map(x=>T[x].ad).join(' ve ')} yanına hitap ediyor`);
    const n=D.prog.filter(p=>p.bolum===b.ad).length;if(n)r.push(`Listemizde bu alanda ${n} doğrulanmış lisans programı var`);
    return r};
  const out={pc,code,ord,bol:pick.map(b=>({ad:b.ad,kod:b.kod,sayfa:b.sayfa,why:bolWhy(b)})),tracks:[]};
  const order=['Campus','Next','Prep','Summer'].filter(p=>progs.includes(p));
  order.forEach(p=>{
    if(p==='Campus'){
      const rel=D.prog.filter(x=>topSet.has(x.bolum)&&UL[x.ulke]);
      const byC={};rel.forEach(x=>(byC[x.ulke]=byC[x.ulke]||[]).push(x));
      const cs=Object.keys(byC).map(c=>{const s=cscore(UL[c],p);const n=byC[c].length;return {c,s:s.s+Math.min(4,n*0.6),why:[...s.why,`Profiline uyan ${n} İngilizce lisans programı`],items:byC[c]}}).sort((x,y)=>y.s-x.s).slice(0,3);
      cs.forEach(c=>{c.items.sort((x,y)=>rank[x.bolum]-rank[y.bolum]);const seenU={},seenB={},sel=[];for(const x of c.items){if(seenU[x.uni]>=2||seenB[x.bolum])continue;sel.push(x);seenU[x.uni]=(seenU[x.uni]||0)+1;seenB[x.bolum]=1;if(sel.length>=4)break}c.items=sel});
      out.tracks.push({p,countries:cs.map(c=>({ulke:c.c,why:c.why,items:c.items.map(x=>({ad:x.uni,alt:x.program,bolum:x.bolum,sehir:x.sehir,url:x.url}))}))});
    } else if(p==='Prep'){
      const cur=multi('mufredat');const byC={};
      D.okul.forEach(o=>{const u=UL[o.ulke];if(!u)return;let sc=0;const w=[];
        if(cur.includes('IB')&&o.mufredat.includes('IB')){sc+=3;w.push('IB')}if(cur.includes('Abitur')&&o.mufredat.includes('Abitur')){sc+=3;w.push('Abitur')}if(cur.includes('Fransız Bac')&&o.mufredat.includes('Fransız Bac')){sc+=3;w.push('Fransız Bac')}
        (byC[o.ulke]=byC[o.ulke]||[]).push({o,sc,w})});
      const cs=Object.keys(byC).map(c=>{const s=cscore(UL[c],p);const m=byC[c].some(x=>x.sc);return {c,s:s.s+(m?3:0),why:[...s.why,...(m?['Okulundaki müfredatla devam edebileceğin okullar var']:[])],items:byC[c].sort((x,y)=>y.sc-x.sc)}}).sort((x,y)=>y.s-x.s).slice(0,4);
      out.tracks.push({p,countries:cs.map(c=>({ulke:c.c,why:c.why,items:c.items.slice(0,3).map(x=>({ad:x.o.ad,alt:x.o.tur,bolum:[x.o.sinif,x.o.mufredat.join(', ')].filter(Boolean).join(' · '),sehir:x.o.sehir,url:x.o.url,tag:x.w.length?x.w.join(', ')+' programı var':''}))}))});
    } else if(p==='Next'){
      const rel=D.prog.filter(x=>topSet.has(x.bolum)&&UL[x.ulke]&&UL[x.ulke].prog.includes('Next'));
      const byC={};rel.forEach(x=>(byC[x.ulke]=byC[x.ulke]||[]).push(x));
      let cs=Object.keys(byC).map(c=>{const s=cscore(UL[c],p);const n=new Set(byC[c].map(x=>x.uni)).size;return {c,s:s.s+Math.min(4,n*0.5),why:[...s.why,`Senin alanlarında bölümü olan ${n} okul`],items:byC[c]}}).sort((x,y)=>y.s-x.s).slice(0,3);
      cs.forEach(c=>{c.items.sort((x,y)=>rank[x.bolum]-rank[y.bolum]);const seenU={},seenB={},sel=[];for(const x of c.items){if(seenU[x.uni]||seenB[x.bolum])continue;sel.push(x);seenU[x.uni]=1;seenB[x.bolum]=1;if(sel.length>=4)break}c.items=sel});
      const MS=/\b(MSc|MA|MBA|LLM|Master|MRes|MPhil|M\.Sc)\b/;
      out.tracks.push({p,note:'Bu okulların hepsinde senin alanlarında bölüm var. Yüksek lisans programını notlarına, deneyimine ve kariyer hedefine göre birlikte seçelim.',countries:cs.map(c=>({ulke:c.c,why:c.why,items:c.items.map(x=>({ad:x.uni,alt:MS.test(x.program)?x.program:x.bolum+' alanında bölümü var',bolum:'',sehir:x.sehir}))}))});
    } else {
      const ENC=['Birleşik Krallık','İngiltere','ABD','Kanada','İrlanda','Avustralya','Yeni Zelanda','Malta'];const okL=u=>ENC.includes(u.ad)||multi('dil').some(l=>(LMAP[l]||[]).includes(u.ad));const cs=D.ulkeler.filter(u=>u.prog.includes('Summer')&&okL(u)).map(u=>({u,...cscore(u,p)})).sort((x,y)=>y.s-x.s).slice(0,3);
      out.tracks.push({p,countries:cs.map(c=>({ulke:c.u.ad,why:c.why,items:[{ad:c.u.yaz,alt:'Yaşa ve seviyeye göre program seçimi',bolum:'',sehir:'',url:'summer.html'}]}))});
    }});
  S.r=out;
}
