  if(sl){const pre=`${sl.src} puanına göre İngilizcen yaklaşık ${sl.lvl} seviyesinde.`;t=pre+' '+t;if(a.eng&&a.eng!=='?'&&a.eng!==sl.lvl)t+=` Kendi tahminin ${a.eng} idi; planı puanına göre kuralım.`;if(multi('prog').includes('Campus')&&CEFR.indexOf(sl.lvl)<3)t+=' Lisans için bir dil ya da hazırlık yılı (foundation) seçeneğini de listeye ekleyelim.'}
